import java.util.Comparator;
import java.util.List;
import java.util.stream.Collector;
import java.util.stream.Collectors;

/** Result of one pass over the data. Provided -- do not edit. */
record Spread(int lowest, int highest, double average) { }

/**
 * TASK: Compute three statistics in a SINGLE stream pass with Collectors.teeing.
 *
 * Collectors.teeing(first, second, merger) feeds every element to two
 * downstream collectors and then merges their two results into one value.
 * Nest a teeing inside a teeing to get three results at once.
 *
 * spreadOf(values) returns a Spread holding:
 *   lowest  -- the smallest value
 *   highest -- the largest value
 *   average -- the mean, ROUNDED to two decimals with Math.round(x * 100.0) / 100.0
 *
 * Example: spreadOf([4, 9, 2]) -> Spread(2, 9, 5.0)
 *          spreadOf([1, 2, 2]) -> Spread(1, 2, 1.67)
 *
 * EDGE CASE: an empty list returns Spread(0, 0, 0.0).
 *
 * TIP: declare the inner collector in its own local variable typed
 *      Collector<Integer, ?, int[]> -- that gives the compiler enough
 *      information to infer the nested generics.
 *
 * RULE: exactly one traversal of the list -- no second stream, no loop.
 */
public class TeeingSpread {

    public static Spread spreadOf(List<Integer> values) {
        Collector<Integer, ?, int[]> ends = Collectors.teeing(
                Collectors.minBy(Comparator.<Integer>naturalOrder()),
                Collectors.maxBy(Comparator.<Integer>naturalOrder()),
                (min, max) -> new int[] { min.orElse(0), max.orElse(0) });

        return values.stream().collect(Collectors.teeing(
                ends,
                Collectors.averagingInt(Integer::intValue),
                (pair, mean) -> new Spread(pair[0], pair[1], Math.round(mean * 100.0) / 100.0)));
    }
}
